WITH src AS (SELECT * FROM transactions WHERE txn_type = 'FEE' AND (txn_time >= '2024-03-01' OR TO_DATE(txn_time) >= '2025-01-01')), amount_bucket_summary AS (SELECT CASE WHEN amount >= 4500 THEN 'high' WHEN amount >= 600 THEN 'mid' ELSE 'low' END AS amount_bucket, CASE WHEN txn_type IN ('CREDIT', 'DEBIT') THEN 'core' ELSE 'other' END AS txn_type_group, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list, COUNT(amount) AS amount_count FROM src GROUP BY CASE WHEN amount >= 4500 THEN 'high' WHEN amount >= 600 THEN 'mid' ELSE 'low' END, CASE WHEN txn_type IN ('CREDIT', 'DEBIT') THEN 'core' ELSE 'other' END) SELECT amount_bucket, txn_type_group, merchant_list, amount_count FROM amount_bucket_summary WHERE amount_count > 4 ORDER BY txn_type_group DESC, amount_bucket LIMIT 5
